async function loadGridDistance() {
  for(const entry of [registry.supplemental_assets?.wider_grid_coverage,registry.supplemental_assets?.grid_distance_column].filter(Boolean)) {
    try {
      runtimeEvidence.gridDistanceRequests += 1;
      const payload=await fetchImmutable(entry.payload.path);
      invariant(payload.schema===entry.payload.schema && payload.generation===entry.generation,'grid coverage identity mismatch');
      invariant(payload.grid && typeof payload.grid==='object' && !Array.isArray(payload.grid),'grid coverage index missing');
      gridDistance=payload.grid;
      runtimeEvidence.gridDistanceReady=true;
      runtimeEvidence.gridCoverageSource=entry.generation;
      return;
    } catch(error) { runtimeEvidence.gridCoverageFallback=true; }
  }
  gridDistance=null;
}

